    function language(lang,silent=false){let t={...i18n.en,...(i18n[lang]||{}),...(heroRefresh[lang]||{})};document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(x=>{if(t[x.dataset.i18n])x.textContent=t[x.dataset.i18n]});document.querySelectorAll('[data-i18n-html]').forEach(x=>{if(t[x.dataset.i18nHtml])x.innerHTML=t[x.dataset.i18nHtml]});document.querySelectorAll('[data-i18n-placeholder]').forEach(x=>{if(t[x.dataset.i18nPlaceholder])x.placeholder=t[x.dataset.i18nPlaceholder]});document.querySelectorAll('.lang-select').forEach(x=>x.value=lang);localStorage.setItem('svip-lang',lang);if(!silent)toastMsg(lang==='zh'?'语言已切换':'Language switched: '+lang.toUpperCase())}document.querySelectorAll('.lang-select').forEach(s=>s.onchange=()=>language(s.value));language(localStorage.getItem('svip-lang')||'en',true);

