    const basePageLanguage=language;
    let activeLang='en';
    const setOne=(selector,value)=>{const el=document.querySelector(selector);if(el&&value!==undefined)el.textContent=value};
    const setMany=(selector,values)=>{document.querySelectorAll(selector).forEach((el,i)=>{if(values&&values[i]!==undefined)el.textContent=values[i]})};
    function renderLocalizedChecklist(key){const t=localized[activeLang];const rows=t&&t.qcLists&&t.qcLists[key]?t.qcLists[key]:qcData[key];checklist.innerHTML=rows.map(x=>`<li>${x}</li>`).join('')}
    function refreshWeightLabel(){const t=localized[activeLang]||originalCopy;const a=+document.getElementById('weight').value||0,v=((+document.getElementById('length').value||0)*(+document.getElementById('width').value||0)*(+document.getElementById('height').value||0))/(+document.getElementById('divisor').value||6000);document.getElementById('weightType').textContent=v>a?t.vol:t.actual}
    function applyPageCopy(lang,silent=false){
      activeLang=localized[lang]?lang:'en';basePageLanguage(activeLang,true);const t=localized[activeLang]||originalCopy;
      setMany('.popular-searches > *',t.pop);setMany('.hero-microproof span',t.micro);setOne('.hero-edge-note',t.edge);setMany('.proof-item small',t.proof);setOne('#categories .section-copy',t.catIntro);setMany('.category-card h3',t.catNames);setMany('.category-card p',t.catNotes);setOne('#products .eyebrow',t.prodEye);setOne('#products .section-copy',t.prodIntro);setMany('.product-tag',t.prodTags);document.querySelectorAll('.view').forEach(x=>x.textContent=t.view);setOne('.product-note',t.prodNote);setOne('#qc-desk .section-copy',t.toolsIntro);setMany('.tool-kicker',t.toolKickers);setOne('.qc-panel h3',t.qcTitle);setOne('.qc-panel > p',t.qcIntro);setMany('.qc-tabs button',t.qcTabs);setOne('.calc-panel h3',t.calcTitle);setOne('.calc-panel > p:not(.calc-note)',t.calcIntro);setMany('.field label',t.labels);setOne('.calc-result small',t.calcSmall);setOne('.calc-note',t.calcNote);setOne('#how .section-copy',t.howIntro);setMany('.path-card h3',t.pathTitles);setMany('.path-card p',t.pathText);setOne('#guides .section-copy',t.guidesIntro);setMany('.guide-meta span:first-child',t.guideTypes);setMany('.guide-card h3',t.guideTitles);setMany('.guide-card > p',t.guideText);document.querySelectorAll('.guide-open').forEach(x=>x.textContent=t.openGuide);setOne('#allGuides',t.allGuides);setOne('#faq .section-copy',t.faqIntro);setMany('.faq-question > span:nth-child(2)',t.faqQ);setMany('.faq-answer p',t.faqA);setOne('.cta-copy > p:not(.eyebrow)',t.ctaText);setMany('.cta-actions a',t.ctaBtns);setOne('.footer-grid > div:first-child > p',t.footerDesc);setMany('.footer-grid h3',t.footerHeads);setMany('.footer-grid nav a',t.footerLinks);setMany('.copyright span',t.copyright);
      const active=document.querySelector('.qc-tabs button.active');renderLocalizedChecklist(active?active.dataset.qc:'shoes');calculate();refreshWeightLabel();document.querySelectorAll('.lang-select').forEach(x=>x.value=activeLang);localStorage.setItem('svip-lang',activeLang);if(!silent)toastMsg(activeLang==='zh'?'语言已全部切换':'Language switched: '+activeLang.toUpperCase());
    }
    document.querySelectorAll('[data-qc]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-qc]').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderLocalizedChecklist(b.dataset.qc)});
    ['weight','length','width','height','divisor'].forEach(id=>document.getElementById(id).oninput=()=>{calculate();refreshWeightLabel()});
    catalogSearch.onsubmit=e=>{e.preventDefault();let q=searchInput.value.trim(),t=localized[activeLang]||originalCopy;if(!q)return toastMsg(t.searchEmpty);window.open('https://kakobuymake.com/?m=home&c=Search&a=lists&keywords='+encodeURIComponent(q),'_blank','noopener')};
    document.querySelectorAll('.lang-select').forEach(s=>s.onchange=()=>applyPageCopy(s.value));
    window.language=applyPageCopy;applyPageCopy(localStorage.getItem('svip-lang')||'en',true);

const seoArticles={
      qc:{
        title:'How to Read Sugargoo QC Photos: A Risk-Based Inspection Method for Overseas Buyers',
        html:`<p class="eyebrow">SUGARGOO QC FIELD GUIDE · UPDATED AUGUST 2026</p>
        <h2>Five photos are not a verdict. They are an evidence set.</h2>
        <p class="lead">A good Sugargoo QC review does not begin with the question “Does this look nice?” It begins with a sharper question: “What would be expensive to discover only after international delivery?” That change in perspective turns warehouse images from casual browsing material into a practical risk-control tool.</p>
        <p>Sugargoo’s current official guidance says that purchasing orders normally receive five free QC photos after the item is signed into the warehouse. Those images can help confirm visible details before a parcel is submitted for international shipping. The number sounds reassuring, but quantity alone does not create certainty. Five poorly interpreted photographs can still lead to a bad approval, while one carefully requested measurement can prevent a costly mistake.</p>
        <p>This guide presents a decision-led method for reading Sugargoo QC photos. It is designed for overseas buyers who discover products through spreadsheets, catalogue pages, Taobao, Weidian, 1688 or another Chinese marketplace and then use Sugargoo for purchasing, warehouse handling and international delivery. The goal is not to pretend that photographs prove everything. The goal is to extract the maximum useful evidence from what can actually be seen.</p>

        <h3>1. Freeze the order baseline before opening the gallery</h3>
        <p>The most common QC mistake happens before the first photograph is inspected: the buyer no longer has a precise record of what was ordered. A seller page may contain several colours, batches, sizes or accessory combinations. If the buyer remembers only the product title, almost any similar-looking item can appear correct.</p>
        <p>Create a compact order baseline with the exact selected variant, colour, size, quantity, seller notes and any promised accessories. Save the live seller-page context when you place the order because listings can change. The QC task is then a comparison between two defined states: what was selected and what entered the warehouse. Without that baseline, the review becomes an opinion rather than a verification.</p>
        <p>Start with objective facts. Is the quantity correct? Does the size label match the selected size? Is the colour family correct under the warehouse lighting? Are the expected pieces present? For a two-piece set, seeing only the top is not enough. For shoes, confirm that both the left and right shoe are shown. For a bag sold with a strap or pouch, look for the included part rather than assuming it is inside the packaging.</p>

        <h3>2. Read the five standard images as an evidence map</h3>
        <p>Do not review the photos as five isolated pictures. Assign each image a job. One image may establish the full front profile, another the rear, another the label or size tag, and the remaining views may show details or packaging. The exact angles can vary, so focus on coverage rather than expecting a fixed photographic script.</p>
        <p>Build a mental evidence map with four zones. The first is identity: model, colour, size marking and quantity. The second is construction: seams, edges, closures, alignment and attached components. The third is condition: stains, scratches, dents, broken parts, deformation or obvious use. The fourth is shipment impact: retail box, rigid structure, bulky padding, batteries, liquid containers or other attributes that may affect parcel planning.</p>
        <p>A useful review asks what remains unseen after those zones are checked. If the label is blurred, that is a specific information gap. If a bag is photographed only from the front, the back and interior remain uncertain. If a shoe is shown from above but not at heel level, rear alignment remains unknown. Naming the gap makes it possible to decide whether free evidence is sufficient or whether an extra photograph or measurement would change the decision.</p>

        <h3>3. Use category-specific failure points</h3>
        <p>Generic inspection advice loses value quickly. The visible details that matter for a hoodie are not the same as those that matter for sneakers, a structured bag or an electronic device. Use the product category to decide where uncertainty is most expensive.</p>
        <table><tr><th>Category</th><th>High-value visible checks</th><th>What standard photos may miss</th></tr>
        <tr><td>Shoes</td><td>Pair consistency, size tags, toe shape, heel alignment, sole, stitching, visible glue</td><td>Insole length, on-foot fit, hidden internal defects, long-term comfort</td></tr>
        <tr><td>Clothing</td><td>Selected size, print placement, embroidery edges, seams, zipper, buttons, visible colour</td><td>True fabric composition, exact fit, shrinkage, colour accuracy under daylight</td></tr>
        <tr><td>Bags</td><td>Shape, strap, zipper, buckle, edge finish, lining, included accessories</td><td>Interior sections not photographed, material claims, load-bearing durability</td></tr>
        <tr><td>Electronics</td><td>Model marking, colour, plug type, exterior condition, listed accessories</td><td>Battery health, full function, internal condition, route eligibility</td></tr></table>
        <p>For shoes, compare the pair rather than reviewing one shoe at a time. Look for mismatched shape, uneven heel height, inconsistent panels or different sole details. The retail box is also a shipping decision: it may add protection and presentation value, but it can increase parcel volume.</p>
        <p>For clothing, label size is only the beginning. If fit is important, a garment measurement may be more useful than another beauty shot. Look at print centring relative to seams, embroidery tension, zipper tracks, button spacing and whether the front and back appear consistent. Warehouse lighting can shift colour, so avoid treating a small colour difference on screen as conclusive without considering the original listing and lighting conditions.</p>
        <p>For bags, structure and missing accessories often matter more than a perfect logo close-up. Confirm the strap, pouch, dust bag or other promised pieces. Look at zipper paths, edge paint, corners and whether storage has flattened or distorted the body. For electronics, keep the conclusion narrow. A clean exterior and correct model marking do not prove battery condition or complete operation.</p>

        <h3>4. Request extra evidence only when it can change the outcome</h3>
        <p>An extra photo should answer a named question. “More pictures please” is a weak instruction because it leaves the warehouse photographer to guess what matters. A stronger request specifies the object, angle and purpose: photograph the inside size label straight on; measure the insole from heel to toe; show the zipper pull and the area where the strap should attach; place a ruler across the garment chest without stretching the fabric.</p>
        <p>Before buying an add-on, ask what you will do with the result. If a measurement outside your acceptable range would cause a return, the measurement has decision value. If you intend to keep the item regardless, paying for random additional angles may not reduce any real risk. The disciplined buyer purchases evidence, not reassurance.</p>
        <p>Measurements also need definitions. “Length” can mean different points on a garment. State the start and end points. For shoes, say whether you need outsole or removable insole length. For a bag, specify width at the base, height excluding handles, or strap drop. Precise requests reduce ambiguity for both the warehouse and the buyer.</p>

        <h3>5. Separate visible quality from claims photos cannot prove</h3>
        <p>QC photos can support conclusions about visible condition, not every product claim. They do not automatically authenticate a brand, verify fabric composition, prove waterproofing, test long-term durability or reveal internal construction. A photograph of an electronic device switched on once would still not establish battery health or reliable performance over time.</p>
        <p>This boundary is important because overconfidence changes shipping decisions. If the evidence shows the correct visible model with no obvious exterior damage, say exactly that. Do not silently upgrade the conclusion to “fully functional” or “authentic.” Evidence-based language protects the buyer from confusing what is observed with what is hoped.</p>
        <p>Likewise, standard QC is not a substitute for reading the seller listing, checking the selected variant or understanding marketplace risk. The warehouse sees the received item; it does not know every expectation in the buyer’s head. Your order baseline and category checklist provide the missing context.</p>

        <h3>6. Choose one of four clear decisions</h3>
        <p>Every review should end with an action. Approve when the visible facts match the order and the remaining uncertainty is acceptable. Request a retake or extra evidence when an important fact is unreadable or unshown. Seek an exchange when the seller sent the wrong variant or a visible defect but a replacement is available. Return when the mismatch, damage or unresolved uncertainty makes international shipping a poor bet.</p>
        <p>Do not let a low product price weaken the decision standard. International freight, handling time and the difficulty of solving problems after delivery can exceed the value of the item. A cheap product with a known problem is not automatically a bargain. The relevant comparison is the cost of correcting the problem now versus carrying it through international shipping.</p>
        <p>Record the reason for your decision in one sentence. For example: “Approve because model, size tag, colour and both shoes match; minor box damage is acceptable.” Or: “Request insole measurement because seller sizing is unclear and an incorrect length would require return.” A written reason prevents mood, excitement or sunk-cost thinking from replacing the evidence.</p>

        <h3>7. A repeatable Sugargoo QC workflow</h3>
        <ol><li>Save the exact ordered variant, size, colour, quantity and promised accessories.</li><li>Open the warehouse images beside the order baseline.</li><li>Check identity, construction, condition and shipment-impact zones.</li><li>Apply a category-specific checklist instead of generic visual approval.</li><li>Name every meaningful information gap.</li><li>Request only the photo or measurement that can change your decision.</li><li>Choose approve, retake, exchange or return and record the reason.</li><li>After approval, carry packaging and sensitive-item observations into parcel planning.</li></ol>
        <p>The strongest QC habit is proportional confidence. Use Sugargoo’s free images to verify what they genuinely show, buy targeted evidence when a missing fact matters, and refuse to treat unseen properties as confirmed. Five photos cannot eliminate cross-border shopping risk, but a disciplined method can stop visible mistakes before they become expensive international parcels.</p>`
      },
      shipping:{
        title:'Sugargoo Shipping Weight Strategy: Why Cheap Items Become Expensive Parcels',
        html:`<p class="eyebrow">PARCEL PLANNING GUIDE · UPDATED AUGUST 2026</p>
        <h2>The product price ends at checkout. Parcel economics begin at the warehouse.</h2>
        <p class="lead">A buyer can choose inexpensive products and still create an expensive shipment. The reason is not mysterious: international carriers sell both weight capacity and physical space. The final parcel is judged as a package, not as a collection of bargain prices.</p>
        <p>Sugargoo’s official material explains that its pre-shipment package simulation can show actual weight and volumetric weight before shipment. That distinction is the centre of intelligent parcel planning. Actual weight comes from the scale. Volumetric weight converts the parcel’s dimensions into a billing value. Depending on the route, the chargeable weight may be influenced by the greater value, plus route-specific rounding, size limits and item restrictions.</p>
        <p>This guide is not a promise of a particular shipping price. Rates, routes, divisors, restrictions and destination rules can change. Instead, it provides a durable method for understanding why a haul becomes costly and what decisions should be made before the buyer submits the parcel in Sugargoo.</p>

        <h3>1. Stop using item weight as a shipping quote</h3>
        <p>The weight shown for an individual warehouse item is useful, but it is not the complete parcel. International shipment includes outer packaging, protection, consolidation choices and the empty air created by product shapes. A row of small item weights cannot reveal the final box dimensions.</p>
        <p>Imagine a parcel containing one pair of shoes in a retail box, a puffer jacket, a structured handbag and several T-shirts. The shirts may contribute most of the dense mass, but the shoe box, puffer and handbag can determine the outside dimensions. The carrier cannot fill that occupied space with another customer’s cargo, so space can have a price even when the scale reading looks modest.</p>
        <p>Use estimated item weight only for early planning. Treat it as an input, not an invoice. The closer you move to shipment, the more the physical parcel matters. That is why packing decisions and pre-shipment measurement are more informative than adding catalogue weights in a spreadsheet.</p>

        <h3>2. Understand actual, volumetric and chargeable weight</h3>
        <p>Actual weight is the measured mass of the finished parcel. Volumetric weight is commonly calculated from length multiplied by width multiplied by height, divided by a route-specific divisor. A lower divisor produces a higher volumetric result, while a higher divisor produces a lower result. The exact billing rule belongs to the selected live route.</p>
        <p>Suppose a packed box measures 42 × 32 × 24 centimetres. Its volume is 32,256 cubic centimetres. Dividing by 6,000 gives approximately 5.38 kilograms. If the actual parcel weighs 2.4 kilograms and the route uses the higher value for billing, empty space has effectively added almost three kilograms of chargeable weight. This example is a planning model, not a universal Sugargoo quotation.</p>
        <p>Rounding also matters. Some routes bill in increments, apply minimum weights or use size thresholds. Two parcels with similar measurements can therefore receive different quotes when their destinations, item attributes or available lines differ. Never transplant another buyer’s route result into your own parcel without checking the live account.</p>

        <h3>3. Find the volume controller</h3>
        <p>Every bulky parcel usually has one or two items that control the outside box. Call them volume controllers. Removing several socks may change weight slightly but do nothing to the box. Removing one low-value shoe box, compressing a puffer jacket appropriately or separating a rigid presentation case may reduce a dimension and change the volumetric result.</p>
        <p>Common volume controllers include shoe boxes, puffer jackets, structured bags, gift boxes, helmets, large toys, thick protective foam and long objects. Identify them before purchase when possible. Product discovery should include a shipping question: “What shape will this item force the warehouse to build around?”</p>
        <p>Shape matters as much as raw volume. Two rigid objects may not nest efficiently. A bag with fixed handles can create unusable space. A long object may push a parcel over a route’s dimensional limit even when total weight is low. Planning by kilograms alone hides these problems.</p>

        <h3>4. Decide what packaging earns its space</h3>
        <p>Removing retail packaging is not automatically smart. Packaging can provide crush protection, presentation value, resale value or easier storage after delivery. The decision should compare saved volume with the consequences of reduced protection.</p>
        <p>For ordinary clothing, unnecessary retail bags or cardboard inserts may offer little value. For shoes, a box can protect shape but also consume significant space. For glasses, watches or delicate accessories, a rigid case may be more valuable than its freight cost. For a structured handbag, aggressive compression can trade shipping savings for permanent creasing.</p>
        <p>Use QC photos to see what packaging arrived. Then assign each layer one of three labels: essential protection, optional presentation or disposable bulk. This simple classification produces better instructions than a universal “remove all packaging” request. If you remove a layer, decide whether replacement protection is needed.</p>

        <h3>5. Consolidation saves handling, not automatically money</h3>
        <p>Combining several orders into one international parcel can reduce duplicated outer packaging and avoid paying separate minimum charges. It also creates the chance to organise items efficiently. But consolidation can produce a larger dimensional box or push the shipment beyond a favourable route threshold.</p>
        <p>The correct question is not “Is one parcel always cheaper?” It is “Which parcel arrangement fits the available routes and my risk tolerance?” A dense clothing group may combine efficiently. A restricted electronic item, liquid or oversized product may reduce route choices for the entire parcel. Separating it can sometimes preserve better options for ordinary goods.</p>
        <p>Destination customs practices, declared value strategy, route limits and loss exposure can also influence whether a haul should be split. Avoid arbitrary rules such as always shipping exactly a certain weight. Sugargoo’s live routes and your own account details are the final planning environment.</p>

        <h3>6. Treat sensitive attributes as a route filter</h3>
        <p>Sugargoo’s official shipping guidance distinguishes ordinary goods from sensitive or prohibited items. Batteries, liquids, magnets, perfumes, cosmetics and powered devices can face additional conditions or reduced route availability. Exact acceptance varies by product, destination and line.</p>
        <p>A sensitive item changes more than its own shipping cost. If it is placed in a mixed parcel, it can remove routes that would otherwise accept the clothing and shoes. Confirm the item attribute before building the parcel. A low-cost electronic accessory is not cheap if it forces the rest of the haul onto a less suitable route.</p>
        <p>Visual QC cannot settle every classification. A photo may show a power bank or liquid bottle, but capacity, composition and route eligibility require the platform’s current rules. Use warehouse information and Sugargoo’s live route results rather than guessing from appearance.</p>

        <h3>7. Use package simulation when uncertainty is expensive</h3>
        <p>Pre-shipment package simulation is most valuable when estimated and physical outcomes could diverge: several bulky items, uncertain box removal, a route with strict dimensional rules, or a haul where a small measurement change could alter the bill. The service is not merely about getting another number. It converts a hypothetical parcel into measured packaging information.</p>
        <p>Prepare clear instructions before simulation. State which retail boxes to remove, which items require protection and whether compression is acceptable. If you change the packing requirements afterward, the earlier measurement may no longer represent the final parcel. Measurement quality depends on a stable packing brief.</p>
        <p>When the result arrives, compare actual and volumetric weight, identify the controlling dimension and review the live route list. If volumetric weight dominates, ask which packaging or item creates the space. If actual weight dominates, removing air may not materially change billing, although it can still affect route limits and protection.</p>

        <h3>8. Compare routes only after defining the parcel</h3>
        <p>Delivery estimates and prices make sense only after destination, weight, dimensions and item attributes are defined. Compare routes on more than the lowest headline number. Consider tracking quality, estimated time, tax handling, insurance options, restrictions, size limits and the value of the contents.</p>
        <p>A route that is cheap for ordinary clothing may reject a battery. A fast line may have a strict dimension threshold. A tax-handling option may be relevant in one destination and not another. The route decision should be made inside Sugargoo with the final parcel facts visible, not copied from an old social-media screenshot.</p>
        <p>Keep a planning margin. Product packaging, warehouse protection and measurement rounding can create small differences. If your parcel sits exactly at a route boundary, a minor change can affect eligibility or price. Robust planning avoids relying on a perfect estimate.</p>

        <h3>9. A practical parcel-control sequence</h3>
        <ol><li>Before purchase, identify bulky, rigid, long or sensitive items.</li><li>At warehouse arrival, use QC to confirm packaging and visible attributes.</li><li>Label packaging as essential, optional or disposable.</li><li>Group ordinary goods and consider separating route-limiting items.</li><li>Estimate actual and volumetric scenarios with realistic dimensions.</li><li>Use package simulation when dimensional uncertainty could change the decision.</li><li>Compare live Sugargoo routes after the parcel is defined.</li><li>Balance price with protection, tracking, restrictions, time and loss exposure.</li></ol>
        <p>Shipping savings come from controlling parcel geometry, not simply buying lighter products. The disciplined buyer identifies the volume controller, preserves only packaging that earns its space, isolates attributes that restrict routes and measures before committing when uncertainty is costly. That method remains useful even when rates and routes change, because it is built around the physical parcel rather than a temporary price table.</p>`
      },
      links:{
        title:'From Product Link to Sugargoo DIY Order: A Clean Submission Workflow',
        html:`<p class="eyebrow">PRODUCT LINK & DIY ORDER GUIDE · UPDATED AUGUST 2026</p>
        <h2>A spreadsheet row is a lead. A complete order is a specification.</h2>
        <p class="lead">Product discovery moves quickly. A buyer sees an image, price and short title, then clicks through to a marketplace listing. Ordering requires a different standard. Sugargoo’s purchasing team needs a live product source and enough structured information to identify exactly what the buyer wants.</p>
        <p>Sugargoo’s official guidance explains that buyers can paste supported marketplace links into the platform. When a link does not parse correctly, DIY Order provides a manual submission path where the buyer enters product information, price, local shipping and relevant details. This fallback is useful, but it does not repair a vague or expired product lead. Manual ordering works best when the buyer first cleans the source information.</p>
        <p>This guide shows how to move from a Kakobuy catalogue card, spreadsheet row, Taobao link, Weidian listing, 1688 page or other discovery source to a clear Sugargoo order instruction. The method focuses on traceability: every important field should point back to a visible seller fact or an explicit buyer choice.</p>

        <h3>1. Identify what kind of link you actually have</h3>
        <p>Not every URL is a product-detail page. A shop homepage, search result, image album, mobile share redirect, short link or social post may help discovery, but it does not necessarily identify one purchasable item. Before submitting anything, open the destination and ask whether it exposes the seller, product, selectable variants, price context and domestic delivery information.</p>
        <p>A good order source should make it possible to answer five questions: What exact product is being sold? Which seller offers it? What options can be selected? What price applies to the chosen option? What domestic shipping condition is shown? If the page cannot answer those questions, the URL is still a lead rather than a complete order source.</p>
        <p>Catalogue sites such as kakobuymake.com can organise discovery and provide a convenient bridge to product pages. Still, the buyer should verify the live destination before payment. Catalogue names, images and prices can become stale after a seller changes the underlying listing.</p>

        <h3>2. Remove tracking noise without destroying identity</h3>
        <p>Mobile marketplace links often include campaign parameters, share codes or redirects. Noise can interfere with parsers, but aggressive editing can also remove the product identifier. The safest method is to open the share link, allow it to reach the final product-detail page, and copy the stable address from that page.</p>
        <p>Do not invent a “clean” URL by guessing the product number or deleting unfamiliar parameters at random. Test the copied link in a fresh browser state when practical. It should open the same seller and item without relying on your private session. If the page requires login, note that limitation and retain screenshots or seller information for the DIY Order form.</p>
        <p>Shortened links deserve extra attention because their destination can change or expire. A screenshot alone is also insufficient: it can show an item but not prove the current seller, price or selectable options. Preserve both the visual reference and the active source whenever possible.</p>

        <h3>3. Rebuild the order as a six-field specification</h3>
        <p>A reliable order instruction can be reduced to six fields: source URL, product name, exact variant, quantity, price and domestic shipping. Add a seventh field—buyer remarks—only when the seller needs information that is not already expressed by the variant selection.</p>
        <table><tr><th>Field</th><th>Strong input</th><th>Weak input</th></tr>
        <tr><td>Source URL</td><td>Complete live product-detail page</td><td>Shop homepage or social post</td></tr>
        <tr><td>Product name</td><td>Neutral description tied to the listing</td><td>“Same as picture”</td></tr>
        <tr><td>Variant</td><td>Exact seller option text, colour, size or model</td><td>“Large black one” when several exist</td></tr>
        <tr><td>Quantity</td><td>Explicit number and set composition</td><td>Assuming one listing equals one piece</td></tr>
        <tr><td>Price</td><td>Price for the selected option</td><td>Lowest headline price on a multi-option page</td></tr>
        <tr><td>Domestic shipping</td><td>Seller’s shown fee or clearly noted uncertainty</td><td>Leaving it blank without checking</td></tr></table>
        <p>Use the seller’s exact option language when possible. If the marketplace shows colour codes, batch names or model numbers, copy them precisely. Translating everything into a casual nickname can create ambiguity for the purchasing agent. A screenshot with the selected option highlighted can support the text, but it should not replace text.</p>

        <h3>4. Distinguish product price from order cost</h3>
        <p>A catalogue price is not automatically the final purchase amount. The selected variant may cost more than the lowest displayed option. Domestic shipping from seller to warehouse may be separate. Quantity tiers, deposits, minimum order quantities or seller changes can also affect the amount.</p>
        <p>For 1688 listings, pay close attention to minimum quantities and tiered pricing. For second-hand or unique-item marketplaces, confirm whether the item is still available and whether the seller requires communication before purchase. For ordinary Taobao or Weidian products, verify that the selected SKU remains active.</p>
        <p>When the price in your discovery source differs from the live seller page, use the current seller information and decide whether the change is acceptable. Do not force an outdated catalogue price into the DIY Order form and expect the purchasing team to reconstruct the discrepancy.</p>

        <h3>5. Write remarks that reduce—not create—ambiguity</h3>
        <p>Useful remarks contain instructions the seller or buyer needs to act on. Examples include an exact model code, a request to confirm a set contains two named pieces, or a clear note that purchase should not proceed if a specified variant is unavailable.</p>
        <p>Weak remarks include “best quality,” “make sure it is perfect,” “same as photo” or “contact me if anything is wrong.” They do not define a measurable requirement. A purchasing agent cannot guarantee subjective quality from a vague sentence, and the warehouse QC team cannot compare an item against an expectation that was never specified.</p>
        <p>Keep remarks short enough to be operational. If your order requires a long explanation to distinguish the product, the source listing may not be clear enough. Return to the seller page and look for a better-defined option or obtain confirmation before submitting.</p>

        <h3>6. Use DIY Order as a controlled fallback</h3>
        <p>Sugargoo’s DIY Order is valuable when automatic link conversion fails or a supported page cannot be parsed. The official workflow asks the buyer to enter product basics, pricing and local shipping, then review restrictions before submission. Treat the form as a manual reconstruction of the live listing.</p>
        <p>Prepare the fields before opening the form. Keep the product link, title, selected option, quantity, price, domestic shipping, seller name and screenshots together. This reduces the chance of switching tabs and copying details from the wrong item. If information is genuinely unknown, label it as unknown rather than guessing.</p>
        <p>Manual entry transfers more responsibility to the buyer. An automatic parser may import option structures directly, while DIY Order relies on the details you provide. Review every field as though another person must purchase the item without seeing your browsing history—because that is effectively the task.</p>

        <h3>7. Check restrictions before the warehouse becomes the problem</h3>
        <p>Sugargoo’s official guidance notes that batteries, liquids, magnets, perfumes, cosmetics, food, medicine and other sensitive goods may require special routes or may not be accepted. Restrictions depend on the specific item, destination and available shipping line.</p>
        <p>Do not postpone this question until parcel submission. A product can be purchasable domestically and still be difficult to ship internationally. The buying decision should include likely route eligibility, especially for electronics, powered devices, liquid products, aerosols and oversized goods.</p>
        <p>If the item has a battery, record whether it is built in or separate and note any visible capacity information. For liquids, preserve the stated volume and product type. For magnets or unusual materials, provide accurate descriptions. Never misdeclare an item to unlock a route; inaccurate information can create operational and customs risk.</p>

        <h3>8. Build a confirmation gate before payment</h3>
        <p>Before submitting the order, run a final gate. Open the source URL again. Confirm that the seller and product are unchanged. Match the DIY fields against the page. Check the exact option and quantity. Recalculate the item price and domestic shipping. Review the sensitive-item question. Save a dated screenshot of the selected state if the listing is likely to change.</p>
        <p>Then define your tolerance for seller changes. If the chosen colour is unavailable, should the order be cancelled or substituted? If the price increases slightly, should purchasing continue? Clear boundaries reduce back-and-forth and prevent an unwanted replacement.</p>
        <p>After purchase, the workflow continues. Track the order to warehouse arrival, then compare the Sugargoo QC photos with the same baseline used at submission. A clean order instruction and a disciplined QC review are two halves of the same control system.</p>

        <h3>9. What to do when the link dies after purchase</h3>
        <p>Seller pages can disappear, change options or redirect after an order is placed. This is why the saved baseline matters. Keep the product title, seller identity, selected SKU, screenshots and original URL. When the item arrives, those records allow a meaningful comparison even if the live listing no longer exists.</p>
        <p>If the link dies before purchase, do not submit a speculative DIY Order based only on an old image and price. Look for the current seller page or another active option. If the product is unique and seller communication is possible, obtain the missing information first.</p>
        <p>If parsing alone fails but the live page is intact, DIY Order is appropriate. The distinction is crucial: a parser problem is a technical obstacle; a missing product identity is an evidence problem. Manual entry solves the first, not the second.</p>

        <h3>10. The clean submission checklist</h3>
        <ol><li>Open the final live product-detail page.</li><li>Confirm seller, product identity and current availability.</li><li>Copy the exact variant text, quantity and selected-option price.</li><li>Check domestic shipping and minimum-order conditions.</li><li>Save useful screenshots without relying on them as the only source.</li><li>Assess batteries, liquids, magnets, size and other route-sensitive attributes.</li><li>Use automatic parsing when it accurately imports the listing.</li><li>Use DIY Order when parsing fails but product identity remains clear.</li><li>Set cancellation or substitution boundaries in precise remarks.</li><li>At warehouse arrival, compare QC against the saved order baseline.</li></ol>
        <p>The best Sugargoo order is not the one with the longest note. It is the one another person can execute without guessing. Treat every spreadsheet row as a discovery lead, rebuild it as a traceable specification, and use DIY Order only after the product source is clear. That discipline prevents link errors from becoming wrong purchases and gives the later QC review a factual baseline.</p>`
      }
    };

    originalCopy.guideTitles=[seoArticles.qc.title,seoArticles.shipping.title,seoArticles.links.title];
    originalCopy.guideText=['A risk-based method for turning five warehouse images into an approve, retake, exchange or return decision.','Control actual weight, volumetric weight, packaging, consolidation and route-limiting attributes.','Convert a product lead into a complete, traceable Sugargoo purchasing instruction.'];
    setMany('.guide-card h3',originalCopy.guideTitles);setMany('.guide-card > p',originalCopy.guideText);document.querySelectorAll('.guide-meta span:last-child').forEach(x=>x.textContent='9 MIN');
    function openSeoArticle(key){const item=seoArticles[key];if(!item)return;modalTitle.textContent=item.title;articleBody.innerHTML=item.html;modal.classList.add('open');document.body.classList.add('lock');modal.querySelector('.modal-panel').scrollTop=0}
    function openSeoLibrary(){modalTitle.textContent='All Buyer Guides';articleBody.innerHTML=`<p class="eyebrow">SUGARGOO BUYER RESEARCH</p><h2>All three in-depth guides.</h2><p class="lead">Choose a guide below. Each article is an original, practical English resource built from current Sugargoo service information and cross-border purchase decision points.</p><div class="all-guides-grid"><button class="all-guides-item seo-list-open" data-open="qc"><small>QC PHOTOS · 9 MIN</small><h3>${seoArticles.qc.title}</h3><p>Turn five standard warehouse images into a repeatable approve, retake, exchange or return decision.</p></button><button class="all-guides-item seo-list-open" data-open="shipping"><small>PARCEL PLANNING · 9 MIN</small><h3>${seoArticles.shipping.title}</h3><p>Control actual weight, volumetric weight, packaging, consolidation and route-limiting attributes.</p></button><button class="all-guides-item seo-list-open" data-open="links"><small>DIY ORDER · 9 MIN</small><h3>${seoArticles.links.title}</h3><p>Convert a product lead into a complete, traceable Sugargoo purchasing instruction.</p></button></div>`;modal.classList.add('open');document.body.classList.add('lock');modal.querySelector('.modal-panel').scrollTop=0;articleBody.querySelectorAll('.seo-list-open').forEach(b=>b.onclick=()=>openSeoArticle(b.dataset.open))}
